-- Dump demo app-bengkel, dibuat 2026-11-25 21:34 WIB.
-- Isi: data demo dengan booking untuk hari ini, besok, dan lusa (2 hari ke depan).
-- Restore: sqlite3 database/database.sqlite < database/dumps/demo-2hari-2026-11-25.sql
-- Catatan: tanggal ikut tanggal pembuatan; buat ulang dengan migrate:fresh --seed bila demo mundur.

PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "role" varchar not null default 'kasir', "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" text not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "customers" ("id" integer primary key autoincrement not null, "name" varchar not null, "phone" varchar, "email" varchar, "address" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "vehicles" ("id" integer primary key autoincrement not null, "customer_id" integer not null, "plate_number" varchar not null, "type" varchar not null, "brand" varchar not null, "model" varchar not null, "year" integer, "created_at" datetime, "updated_at" datetime, foreign key("customer_id") references "customers"("id") on delete restrict);
CREATE TABLE IF NOT EXISTS "mechanics" ("id" integer primary key autoincrement not null, "name" varchar not null, "phone" varchar, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "services" ("id" integer primary key autoincrement not null, "name" varchar not null, "price" integer not null, "est_minutes" integer not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "spareparts" ("id" integer primary key autoincrement not null, "sku" varchar not null, "name" varchar not null, "price" integer not null, "stock" integer not null, "min_stock" integer not null default '5', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "work_orders" ("id" integer primary key autoincrement not null, "vehicle_id" integer not null, "user_id" integer not null, "mechanic_id" integer, "queue_date" date not null, "queue_number" integer not null, "tracking_code" varchar not null, "complaint" text, "status" varchar not null default 'menunggu', "public_note" text, "started_at" datetime, "finished_at" datetime, "discount" integer not null default '0', "total" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("vehicle_id") references "vehicles"("id") on delete restrict, foreign key("user_id") references "users"("id") on delete restrict, foreign key("mechanic_id") references "mechanics"("id") on delete restrict);
CREATE TABLE IF NOT EXISTS "work_order_services" ("id" integer primary key autoincrement not null, "work_order_id" integer not null, "service_id" integer not null, "price" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("work_order_id") references "work_orders"("id") on delete cascade, foreign key("service_id") references "services"("id") on delete restrict);
CREATE TABLE IF NOT EXISTS "work_order_parts" ("id" integer primary key autoincrement not null, "work_order_id" integer not null, "sparepart_id" integer not null, "qty" integer not null, "price" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("work_order_id") references "work_orders"("id") on delete cascade, foreign key("sparepart_id") references "spareparts"("id") on delete restrict);
CREATE TABLE IF NOT EXISTS "payments" ("id" integer primary key autoincrement not null, "work_order_id" integer not null, "method" varchar not null, "amount" integer not null, "paid_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("work_order_id") references "work_orders"("id") on delete restrict);
CREATE TABLE IF NOT EXISTS "work_order_status_logs" ("id" integer primary key autoincrement not null, "work_order_id" integer not null, "user_id" integer, "from_status" varchar, "to_status" varchar not null, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("work_order_id") references "work_orders"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "bookings" ("id" integer primary key autoincrement not null, "booking_code" varchar not null, "customer_name" varchar, "phone" varchar, "email" varchar, "plate_number" varchar not null, "vehicle_type" varchar not null, "brand" varchar not null, "model" varchar not null, "service_id" integer, "complaint" text, "booking_date" date not null, "slot_time" varchar not null, "status" varchar not null default 'menunggu', "staff_note" text, "work_order_id" integer, "created_at" datetime, "updated_at" datetime, "dp_amount" integer not null default '0', "dp_paid_at" datetime, "dp_method" varchar, "dp_proof_path" varchar, "dp_proof_at" datetime, foreign key("service_id") references "services"("id") on delete restrict, foreign key("work_order_id") references "work_orders"("id") on delete restrict);
CREATE TABLE IF NOT EXISTS "notification_logs" ("id" integer primary key autoincrement not null, "type" varchar not null, "channel" varchar not null, "recipient" varchar not null, "work_order_id" integer, "booking_id" integer, "status" varchar not null, "error" text, "sent_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("work_order_id") references "work_orders"("id") on delete set null, foreign key("booking_id") references "bookings"("id") on delete set null);
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "personal_access_tokens_tokenable_type_tokenable_id_index" on "personal_access_tokens" ("tokenable_type", "tokenable_id");
CREATE UNIQUE INDEX "personal_access_tokens_token_unique" on "personal_access_tokens" ("token");
CREATE INDEX "personal_access_tokens_expires_at_index" on "personal_access_tokens" ("expires_at");
CREATE UNIQUE INDEX "vehicles_plate_number_unique" on "vehicles" ("plate_number");
CREATE UNIQUE INDEX "spareparts_sku_unique" on "spareparts" ("sku");
CREATE UNIQUE INDEX "work_orders_queue_date_queue_number_unique" on "work_orders" ("queue_date", "queue_number");
CREATE UNIQUE INDEX "work_orders_tracking_code_unique" on "work_orders" ("tracking_code");
CREATE UNIQUE INDEX "work_order_services_work_order_id_service_id_unique" on "work_order_services" ("work_order_id", "service_id");
CREATE UNIQUE INDEX "work_order_parts_work_order_id_sparepart_id_unique" on "work_order_parts" ("work_order_id", "sparepart_id");
CREATE INDEX "bookings_booking_date_slot_time_index" on "bookings" ("booking_date", "slot_time");
CREATE UNIQUE INDEX "bookings_booking_code_unique" on "bookings" ("booking_code");
CREATE UNIQUE INDEX "bookings_work_order_id_unique" on "bookings" ("work_order_id");
COMMIT;
